package com.braziliansoccer.mcp;

import java.io.*;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.*;

/** Stdio MCP server. Start with: java -jar target/brazilian-soccer-mcp-1.0.0.jar [data/kaggle]. */
public final class BrazilianSoccerMcpServer {
    private final SoccerRepository repository; private final SoccerService soccer;
    BrazilianSoccerMcpServer(SoccerRepository repository) { this.repository=repository; this.soccer=new SoccerService(repository); }
    public static void main(String[] args) throws Exception { Path data=Path.of(args.length == 0 ? "data/kaggle" : args[0]); new BrazilianSoccerMcpServer(SoccerRepository.load(data)).serve(System.in,System.out); }
    void serve(InputStream input, PrintStream output) throws IOException { try (BufferedReader reader=new BufferedReader(new InputStreamReader(input))) { for(String line;(line=reader.readLine())!=null;) { if(!line.isBlank()) { Map<String,Object> request=Json.object(Json.parse(line)); Object response=handle(request); if(response!=null){output.println(Json.stringify(response));output.flush();} } } } }
    Object handle(Map<String,Object> request) { Object id=request.get("id"); String method=str(request.get("method")); if(method.equals("notifications/initialized")) return null;
        try { Object result=switch(method) { case "initialize" -> Map.of("protocolVersion","2024-11-05","capabilities",Map.of("tools",Map.of()),"serverInfo",Map.of("name","brazilian-soccer-mcp","version","1.0.0")); case "tools/list" -> Map.of("tools",tools()); case "tools/call" -> call(Json.object(request.get("params"))); default -> throw new IllegalArgumentException("Unsupported method: "+method); }; return Map.of("jsonrpc","2.0","id",id,"result",result); } catch(Exception e) { return Map.of("jsonrpc","2.0","id",id,"error",Map.of("code",-32602,"message",e.getMessage())); } }
    private List<Map<String,Object>> tools() { return List.of(
            tool("search_matches","Find matches by team, opponent, competition, season, date range, or cup round/stage.", "team,opponent,competition,season,from,to,round,stage,limit", Set.of()),
            tool("team_statistics","Calculate a team's wins, draws, losses, goals, and win rate.", "team,season,competition,venue", Set.of("team")),
            tool("head_to_head","Compare two teams directly.", "team,opponent,season,competition", Set.of("team","opponent")),
            tool("search_players","Find FIFA players by name, nationality, club, or position, ordered by rating.", "name,nationality,club,position,limit", Set.of()),
            tool("standings","Calculate a competition table from match results.", "season,competition", Set.of()),
            tool("competition_statistics","Get goals-per-match, home-win-rate, and biggest victories.", "season,competition,limit", Set.of()),
            tool("answer_question","Answer a common natural-language soccer question. Use structured tools where exact filters are important.", "question", Set.of("question"))); }
    private static Map<String,Object> tool(String name,String description,String names,Set<String> required){Map<String,Object> properties=new LinkedHashMap<>();for(String property:names.split(","))properties.put(property,Map.of("type",property.equals("season")||property.equals("limit")?"integer":"string"));Map<String,Object> schema=new LinkedHashMap<>();schema.put("type","object");schema.put("properties",properties);if(!required.isEmpty())schema.put("required",required);schema.put("additionalProperties",false);return Map.of("name",name,"description",description,"inputSchema",schema);}
    private Map<String,Object> call(Map<String,Object> params) { String name=str(params.get("name"));Map<String,Object> a=Json.object(params.get("arguments")); Object data=switch(name) { case "search_matches"->matches(a);case "team_statistics"->stats(a);case "head_to_head"->headToHead(a);case "search_players"->players(a);case "standings"->standings(a);case "competition_statistics"->competition(a);case "answer_question"->answer(str(a.get("question")));default->throw new IllegalArgumentException("Unknown tool: "+name);}; return Map.of("content",List.of(Map.of("type","text","text",Json.stringify(data))),"structuredContent",data); }
    private Map<String,Object> matches(Map<String,Object>a){ List<Match> found=repository.findMatches(new MatchFilter(str(a.get("team")),str(a.get("opponent")),str(a.get("competition")),integer(a.get("season")),date(a.get("from")),date(a.get("to")),first(str(a.get("round")),str(a.get("stage"))),limit(a)));return Map.of("count",found.size(),"matches",found.stream().map(this::match).toList()); }
    private Map<String,Object> stats(Map<String,Object>a){return teamStats(soccer.teamStats(required(a,"team"),integer(a.get("season")),str(a.get("competition")),str(a.get("venue"))));}
    private Map<String,Object> headToHead(Map<String,Object>a){String first=required(a,"team");return Map.of("team",first,"opponent",required(a,"opponent"),"record",teamStats(soccer.headToHead(first,required(a,"opponent"),integer(a.get("season")),str(a.get("competition")))));}
    private Map<String,Object> players(Map<String,Object>a){List<Player> found=repository.findPlayers(str(a.get("name")),str(a.get("nationality")),str(a.get("club")),str(a.get("position")),limit(a));return Map.of("count",found.size(),"players",found.stream().map(this::player).toList());}
    private Map<String,Object> standings(Map<String,Object>a){List<TeamStats> table=soccer.standings(integer(a.get("season")),str(a.get("competition")));return Map.of("count",table.size(),"standings",table.stream().map(this::teamStats).toList());}
    private Map<String,Object> competition(Map<String,Object>a){Map<String,Object> result=new LinkedHashMap<>(soccer.aggregate(str(a.get("competition")),integer(a.get("season"))));result.put("biggestWins",soccer.biggestWins(str(a.get("competition")),integer(a.get("season")),limit(a)).stream().map(this::match).toList());return result;}
    private Map<String,Object> answer(String q){if(q==null)throw new IllegalArgumentException("Missing required argument: question");String lower=q.toLowerCase(Locale.ROOT);Integer season=yearIn(q);Map<String,Object> arguments=new LinkedHashMap<>();if(lower.contains("highest")||lower.contains("top")&&lower.contains("player")){if(lower.contains("brazilian"))arguments.put("nationality","Brazil");String club=extractAfter(q," at ");if(!club.isBlank())arguments.put("club",club);arguments.put("limit",10);return players(arguments);}if(lower.contains("standings")||lower.contains("who won")){if(season!=null)arguments.put("season",season);putIf(arguments,"competition",competition(q));return standings(arguments);}if(lower.contains("average goals")||lower.contains("biggest win")){if(season!=null)arguments.put("season",season);putIf(arguments,"competition",competition(q));arguments.put("limit",10);return competition(arguments);}putIf(arguments,"team",teamMention(q));if(season!=null)arguments.put("season",season);putIf(arguments,"competition",competition(q));arguments.put("limit",20);return matches(arguments);}
    private static String competition(String q){String l=q.toLowerCase(Locale.ROOT);return l.contains("libertadores")?"Libertadores":l.contains("copa do brasil")?"Copa do Brasil":l.contains("brasileir")||l.contains("serie a")?"Brasileirão":"";} private static String teamMention(String q){String clean=q.replaceAll("(?i)(when did|what matches did|show me|all|last play|matches|in|the|did|play|vs|versus|\\d{4})", " ").trim().replaceAll("\\s+"," ");return clean;}
    private Map<String,Object> match(Match m){Map<String,Object>x=new LinkedHashMap<>();x.put("date",m.date()==null?null:m.date().toString());x.put("competition",m.competition());x.put("homeTeam",m.homeTeam());x.put("awayTeam",m.awayTeam());x.put("homeGoals",m.homeGoals());x.put("awayGoals",m.awayGoals());x.put("season",m.season());x.put("round",m.round());x.put("stage",m.stage());x.put("stadium",m.stadium());return x;} private Map<String,Object> player(Player p){Map<String,Object>x=new LinkedHashMap<>();x.put("id",p.id());x.put("name",p.name());x.put("age",p.age());x.put("nationality",p.nationality());x.put("overall",p.overall());x.put("potential",p.potential());x.put("club",p.club());x.put("position",p.position());return x;} private Map<String,Object> teamStats(TeamStats t){return Map.of("team",t.team(),"matches",t.matches(),"wins",t.wins(),"draws",t.draws(),"losses",t.losses(),"goalsFor",t.goalsFor(),"goalsAgainst",t.goalsAgainst(),"points",t.points(),"winRate",t.winRate());}
    private static String str(Object o){return o==null?null:String.valueOf(o).isBlank()?null:String.valueOf(o);} private static void putIf(Map<String,Object> values,String key,String value){if(value!=null&&!value.isBlank())values.put(key,value);} private static String required(Map<String,Object>a,String k){String v=str(a.get(k));if(v==null)throw new IllegalArgumentException("Missing required argument: "+k);return v;} private static Integer integer(Object o){try{return o==null?null:((Number)o).intValue();}catch(Exception e){return null;}} private static LocalDate date(Object o){return o==null?null:SoccerRepository.date(String.valueOf(o));} private static int limit(Map<String,Object>a){Integer l=integer(a.get("limit"));return l==null?100:Math.min(Math.max(l,1),1000);}private static String first(String a,String b){return a!=null?a:b;}private static Integer yearIn(String q){var m=java.util.regex.Pattern.compile("\\b(19|20)\\d{2}\\b").matcher(q);return m.find()?Integer.valueOf(m.group()):null;}private static String extractAfter(String q,String marker){int i=q.toLowerCase(Locale.ROOT).indexOf(marker);return i<0?"":q.substring(i+marker.length()).trim();}
}
